def audit(profile, fabric, proposal):
    try:
        return {"valid": _audit(profile, fabric, proposal)}
    except Exception:
        return {"valid": False}


def _audit(profile, fabric, proposal):
    ptype = type(proposal)
    if ptype is not dict:
        return False
    model = exact.calib_model(profile)
    st = proposal.get('status')
    if not model['feasible']:
        # only the inconsistency certificate can be valid
        if st != 'inconsistent':
            return False
        K, E = exact.exact_edges(profile)
        return exact.check_cycle(proposal.get('cycle'), K, E)
    if st != 'ok':
        return False
    if not exact.verify_calib_artifact(profile, proposal.get('profile'), model):
        return False
    F = fab.Fab(fabric, model['H'])
    P = F.P; N = F.N; V = F.V
    if not _is_int(proposal.get('period_rounds')) or proposal['period_rounds'] != P:
        return False
    peaks_claim = proposal.get('peaks_as')
    if type(peaks_claim) is not list or len(peaks_claim) != len(F.guards):
        return False
    peaks = []
    sel = None
    for gi, g in enumerate(F.guards):
        best, _, _ = F.run_guard(g)
        pk = F.peak_vals(best)
        peaks.append(pk)
        if sel is None and F.is_safe(g, pk):
            sel = g
    for ck, av in zip(peaks_claim, peaks):
        if ck is None:
            if av is not None:
                return False
        else:
            if not _is_int(ck) or ck != av:
                return False
    gclaim = proposal.get('guard_ns')
    if sel is None:
        if gclaim is not None:
            return False
        for key in ('bounds_as', 'age_rounds', 'pred'):
            if proposal.get(key) is not None:
                return False
        if proposal.get('warmup_cycle') is not None:
            return False
        return True
    if not _is_int(gclaim) or gclaim != sel:
        return False
    bm = proposal.get('bounds_as')
    am = proposal.get('age_rounds')
    pm = proposal.get('pred')
    if not _mat_ok(bm, P, N) or not _mat_ok(am, P, N):
        return False
    if type(pm) is not list or len(pm) != P:
        return False
    for row in pm:
        if type(row) is not list or len(row) != N:
            return False
        for c in row:
            if c is None:
                continue
            if type(c) is not list or len(c) != 2 or not all(_is_int(x) for x in c):
                return False
    best, _, _ = F.run_guard(sel, want_pred=False)
    # exact optimal values, nonnegativity and null-pattern agreement
    for p in range(P):
        base = p * N
        for i in range(N):
            v = base + i
            kv = best[v]
            cb = bm[p][i]
            ca = am[p][i]
            if kv >= BIG:
                if cb is not None or ca is not None or pm[p][i] is not None:
                    return False
                continue
            if cb is None or ca is None:
                return False
            if cb < 0 or ca < 0:
                return False
            if cb != kv // AM or ca != kv % AM:
                return False
    # witness edges: every finite non-anchor cell carries a valid attaining
    # step; anchors carry none.  Also closure inequalities.
    adj = F.adj
    werr = F.werr
    NXT = F.NXT
    WCc = F.WC

    def hop_cost(pv, v, code):
        if not (0 <= pv < V):
            return None
        for (u, cc, gm, cd) in adj[pv]:
            if u == v and cd == code and gm >= sel:
                return cc
        return None
    for v in range(V):
        kv = best[v]
        if kv >= BIG:
            continue
        eb = kv // AM
        ea = kv % AM
        p = v // N
        cellp = pm[p][v % N]
        if eb == 0 and ea == 0:
            if cellp is not None:
                return False
        else:
            if cellp is None:
                return False
            pv, code = cellp
            if not (0 <= pv < V):
                return False
            if code == -1:
                if pv != NXT_inv(F, v) or _werr_step(F, pv) is None:
                    return False
                cc = WCc[pv]
            else:
                cc = hop_cost(pv, v, code)
                if cc is None:
                    return False
            pb = bm[pv // N][pv % N]
            pag = am[pv // N][pv % N]
            if pb is None or pag is None:
                return False
            seb = cc // AM
            sea = cc % AM
            if (pb + seb, pag + sea) != (eb, ea):
                return False
            # witness chain decreases age strictly (sea >= 1), so termination
            # is guaranteed by the age ordering; anchors have (0,0).
    # closure: any allowed step from a finite cell goes to a finite cell with
    # label <= source label + contributions
    for v in range(V):
        if best[v] >= BIG:
            continue
        cb = bm[v // N][v % N]
        ca = am[v // N][v % N]
        # wait step
        w = NXT[v]
        dw = bm[w // N][w % N]
        daw = am[w // N][w % N]
        if dw is None or daw is None:
            return False
        if (dw, daw) > (cb + werr[v], ca + 1):
            return False
        for (u, cc, gm, code) in adj[v]:
            if gm < sel:
                continue
            eb2 = bm[u // N][u % N]
            ea2 = am[u // N][u % N]
            if eb2 is None or ea2 is None:
                return False
